CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.+?)\s*->\s*([A-Za-z0-9_]+|End)\s*$")
LINE_RE = re.compile(r"^\s*([^:]+):\s*(.+?)\s*->\s*([A-Za-z0-9_]+|End)\s*$")


def parse_script(text: str):
