    current = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        section_match = SECTION_RE.match(line)
        if section_match:
            current = {"id": section_match.group(1), "lines": []}
            sections.append(current)
            continue

        if current is not None:
            current["lines"].append(line)

    nodes = []
    edges = []
    node_ids = set()

    for section in sections:
        section_id = section["id"]
        lines = section["lines"]

        if not lines:
            continue

        first = lines[0]

        choice_mode = bool(CHOICE_RE.match(first))
        if choice_mode:
            nodes.append({
                "id": section_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            })
            node_ids.add(section_id)

            for line in lines:
                match = CHOICE_RE.match(line)
                if not match:
                    continue
                choice_text, target = match.groups()
                edges.append({
                    "from": section_id,
                    "to": target,
                    "text": choice_text,
                })
        else:
            match = LINE_RE.match(first)
            if not match:
                continue

            speaker, text_value, target = match.groups()
            nodes.append({
                "id": section_id,
                "text": text_value,
                "speaker": speaker,
                "type": "line",
            })
            node_ids.add(section_id)
            edges.append({
                "from": section_id,
                "to": target,
                "text": "",
            })

    referenced = {edge["to"] for edge in edges}
    if "End" in referenced and "End" not in node_ids:
        nodes.append({
            "id": "End",
            "text": "",
            "speaker": "",
            "type": "line",
        })
        node_ids.add("End")

